callGraph.callee:
(() => {
              const r = restaurantById.get(pin.id);
              if (!r) return null;
              return selected === r.id ? (
                <ActiveMapRestaurantMarker
                  restaurant={r}
                  onDetail={onDetail}
                  onClose={onClose}
                />
              ) : (
                <MapRestaurantMarker
                  restaurant={r}
                  highlight={searchResultHighlightState(
                    r.id,
                    selected,
                    hovered,
                    searching,
                  )}
                  onSelect={() => selectRef.current(r.id)}
                  onHover={onHover}
                />
              );
            })
